{
  "skillId": "name-millions-place-value",
  "atomType": "R",
  "theory": {
    "intro": "Large numbers are read in groups of three digits called periods: ones, thousands and millions. Within each period the digits show hundreds, tens and ones.",
    "facts": [
      "From the right, group the digits in **threes**: ones, thousands, millions.",
      "Name the millions group, then thousands, then the final three digits.",
      "The **value** of a digit is the digit multiplied by its place, e.g. the $7$ in $4\\,728\\,000$ is worth $700\\,000$."
    ],
    "steps": [
      "Split the number into periods of three from the right.",
      "Read each group as a number, then add its period name (million / thousand).",
      "A $0$ holds a place — it keeps later digits in the correct column."
    ]
  },
  "practice": {
    "foundation": [
      {
        "question_text": "Write $24\\,613\\,508$ in words.",
        "structure": "numeral-to-words",
        "solution_text": "Periods: $24\\mid 613\\mid 508$\nTwenty-four million, six hundred and thirteen thousand, five hundred and eight."
      },
      {
        "question_text": "Write **seventy-two million, four hundred and six thousand, nineteen** as a numeral.",
        "structure": "words-to-numeral",
        "solution_text": "Periods: $72\\mid 406\\mid 019$\n$=72\\,406\\,019$"
      },
      {
        "question_text": "A city's population is $8\\,035\\,240$.\nRead this number in words.",
        "structure": "numeral-to-words",
        "solution_text": "Periods: $8\\mid 035\\mid 240$\nEight million, thirty-five thousand, two hundred and forty."
      },
      {
        "question_text": "What is the value of the digit $7$ in $17\\,482\\,906$?",
        "structure": "digit-value",
        "solution_text": "The $7$ is in the millions place.\nIts value is $7\\,000\\,000$."
      },
      {
        "question_text": "Which digit is in the hundred-thousands place in $63\\,914\\,275$?",
        "structure": "identify-place",
        "solution_text": "The millions period is $63$ and the thousands period is $914$.\nThe hundred-thousands digit is $9$."
      },
      {
        "question_text": "An astronomy catalogue lists **nine million, two thousand, eighty** objects.\nWrite the count as a numeral.",
        "structure": "words-to-numeral",
        "solution_text": "Periods: $9\\mid 002\\mid 080$\n$=9\\,002\\,080$"
      }
    ],
    "development": [
      {
        "question_text": "Write $305\\,070\\,004$ in words.",
        "structure": "numeral-to-words",
        "solution_text": "Periods: $305\\mid 070\\mid 004$\nThree hundred and five million, seventy thousand and four."
      },
      {
        "question_text": "Write **four hundred and twelve million, nine hundred thousand, six** as a numeral.",
        "structure": "words-to-numeral",
        "solution_text": "Periods: $412\\mid 900\\mid 006$\n$=412\\,900\\,006$"
      },
      {
        "question_text": "A star survey records $76\\,004\\,390$ sources.\nWhat does the digit $4$ represent?",
        "structure": "digit-value",
        "solution_text": "The $4$ is in the thousands place.\nIts value is $4\\,000$."
      },
      {
        "question_text": "In $681\\,250\\,743$, which digit is in the ten-millions place?",
        "structure": "identify-place",
        "solution_text": "The millions period is $681$.\nThe ten-millions digit is $8$."
      },
      {
        "question_text": "A report says **two hundred million, forty-three thousand and twelve** people.\nWrite this population as a numeral.",
        "structure": "words-to-numeral",
        "solution_text": "Periods: $200\\mid 043\\mid 012$\n$=200\\,043\\,012$"
      },
      {
        "question_text": "Read $40\\,000\\,507$ in words.",
        "structure": "zero-period-reading",
        "solution_text": "Periods: $40\\mid 000\\mid 507$\nForty million, five hundred and seven."
      }
    ],
    "mastery": [
      {
        "question_text": "A population has $63$ in the millions period, $5$ in the thousands period and $208$ in the ones period.\nWrite the numeral.",
        "structure": "construct-from-periods",
        "solution_text": "The three periods must each use three places after the first.\n$63\\mid 005\\mid 208$\n$=63\\,005\\,208$"
      },
      {
        "question_text": "A space catalogue number is read as **five hundred and four million, thirty thousand and ninety-two**.\nWhich zeros must be kept when it is written as a numeral?",
        "structure": "words-to-numeral",
        "solution_text": "Periods: $504\\mid 030\\mid 092$\n$=504\\,030\\,092$\nThe zeros hold the hundred-thousands, thousands, hundreds and tens places."
      },
      {
        "question_text": "In $907\\,060\\,401$, name the places occupied by the two digits $6$ and $4$, and state their values.",
        "structure": "two-digit-values",
        "solution_text": "The $6$ is in the ten-thousands place, so its value is $60\\,000$.\nThe $4$ is in the hundreds place, so its value is $400$."
      }
    ]
  }
}

